 wrong=c['plans']['wrong_scope']['actions'];statement=next(z for z in wrong if z.get('target')=='main' and z['action']=='WRITE');wrong.remove(statement);idx=next(i for i,z in enumerate(wrong) if z['action']=='WAIT_FOR_FIELDS');wrong.insert(idx,statement)
 return c

